uses GraphWPF;

begin
  var graph := Dict(
    ('A',Dict(('B',2),('E',5))),
    ('C',Dict(('B',7),('D',9))),
    ('D',Dict(('B',34))),
    ('E',Dict(('C',12),('B',66)))
  );
  var dPoints := new Dictionary<char,Point>;
  var R := 200;
  var n := ('A'..'E').Count;
  var Phi := 0.0; 
  for var c := 'A' to 'E' do
  begin  
    dPoints[c] := Window.Center + R * Vect(Cos(Phi),Sin(Phi));
    Phi += 2 * Pi/n;
  end;

  Window.Title := 'Directed graph drawing';
  var Radius := 10;
  foreach var kv in dPoints do
  begin
    var p := kv.Value;
    Circle(p,Radius);
    TextOut(p.x,p.y,kv.Key,Alignment.Center);
  end;
  foreach var k1 in graph.Keys do
  foreach var k2 in graph[k1].Keys do
  begin
    var weight := graph[k1][k2];
    var (p1,p2) := (dPoints[k1],dPoints[k2]);
    var v := p2 - p1;
    var pp1 := p1 + v.Norm * Radius;
    var pp2 := p2 - v.Norm * Radius;
    Arrow(pp1,pp2);
    var cc := p1 + v/2;
    var txt := weight.ToString;
    var sz := TextSize(txt);
    FillRectangle(cc.X - sz.Width/2, cc.Y - sz.Height/2, sz.Width, sz.Height);
    TextOut(cc.x,cc.y,weight,Alignment.Center);
  end;
end.

type
  Expr = interface
  end;
  Cons = auto class(Expr)
    r: real;
  end;
  Add = auto class(Expr)
    left,right: Expr;
  end;
  Mult = auto class(Expr)
    left,right: Expr;
  end;
  Neg = auto class(Expr)
    ex: Expr;
  end;

function ConsC(r: real) := new Cons(r);
function AddC(l,r: Expr) := new Add(l,r);
function MultC(l,r: Expr) := new Mult(l,r);
function NegC(ex: Expr) := new Neg(ex);

function Eval(e: Expr): real;
begin
  match e with
    Cons(c): Result := c;
    Neg(n): Result := -Eval(n);
    Add(l,r): Result := Eval(l) + Eval(r);
    Mult(l,r): Result := Eval(l) * Eval(r);
  end;
end;  

begin
  var r := AddC(NegC(ConsC(2)),MultC(ConsC(3),ConsC(4)));
  Eval(r).Print;
end.

type
  Expr = interface
  end;
  V = auto class(Expr)
    name: string;
  end;
  Cons = auto class(Expr)
    r: real;
  end;
  Add = auto class(Expr)
    left,right: Expr;
  end;
  Mult = auto class(Expr)
    left,right: Expr;
  end;
  Neg = auto class(Expr)
    ex: Expr;
  end;

function NegC(ex: Expr) := new Neg(ex);  
function ConsC(r: real) := new Cons(r);  
function AddC(ex1,ex2: Expr) := new Add(ex1,ex2);  
function MultC(ex1,ex2: Expr) := new Mult(ex1,ex2);  
function VC(name: string) := new V(name);  

function Simplify(e: Expr): Expr; forward;

function Simplify1(e: Expr): Expr;
begin
  match e with
    Mult(Cons(c),Cons(c1)): Result := ConsC(c*c1);
    Mult(Cons(1.0),ex): Result := Simplify(ex);
    Mult(Cons(0.0),ex): Result := ConsC(0);
    Add(Cons(0.0),ex): Result := Simplify(ex);
    Add(ex,Cons(0.0)): Result := Simplify(ex);
    Add(Cons(c),Cons(c1)): Result := ConsC(c+c1); 
    Add(Cons(c),ex): Result := AddC(ex,ConsC(c)); // constants at the end!
    Mult(Cons(c),ex): Result := MultC(ex,ConsC(c));
    Add(Add(ex,Cons(c)),Cons(c1)): Result := AddC(ex,ConsC(c+c1)); // associativity
    Mult(Mult(ex,Cons(c)),Cons(c1)): Result := MultC(ex,ConsC(c*c1)); // associativity
    Neg(Cons(c)): Result := ConsC(-c); 
    else Result := e;
  end;
end;

function Simplify(e: Expr): Expr;
begin
  match e with
    Mult(e1,e2): Result := Simplify1(MultC(Simplify(e1),Simplify(e2)));
    Add(e1,e2): Result := Simplify1(AddC(Simplify(e1),Simplify(e2)));
    Neg(e1): Result := Simplify1(NegC(Simplify(e1)));
    else Result := e;
  end;
end;

function Str(e: Expr): string;
begin
  match e with
    Mult(l,r): Result := Str(l) + ' * ' + Str(r);
    Add(l,r): Result := Str(l) + ' + ' + Str(r);
    Neg(n): Result := '-' + Str(n);
    Cons(c): Result := c.ToString;
    V(x): Result := x;
  end;
end;

begin
  var r: Expr := AddC(ConsC(1),AddC(MultC(ConsC(1),VC('x')),ConsC(1)));
  r := AddC(r,MultC(ConsC(0),AddC(ConsC(2),VC('a'))));
  r := AddC(r,ConsC(2));
  Str(r).Println;
  r := Simplify(r);
